import appIconData from "./generated/app-icons.json";

/**
 * Render data for every app icon, generated by `pnpm --filter @rezumi/tooling icons:sync` from the Hugeicons Pro export.
 * Keys are the stable Phosphor-style names the web and mobile apps use; the SVG files for every staged icon (app and
 * resume) are under `svg/<style>/<hugeicons-name>.svg` and listed in `catalog.json`.
 */
type AppIconName = keyof typeof appIconData;

type IconTag = "path" | "circle" | "ellipse" | "rect";
/** One SVG element of a 24×24 glyph, with the attributes of the source file (kebab-case, `currentColor` paint). */
type IconNode = readonly [tag: IconTag, attributes: Readonly<Record<string, string>>];

/** Standard stroke for everyday controls; duotone for the selected navigation item and active controls. */
type IconVariant = "stroke" | "duotone";

type AppIconData = { stroke: readonly IconNode[]; duotone?: readonly IconNode[] };

const appIcons = appIconData as unknown as Record<AppIconName, AppIconData>;

/** The glyph for `name` in `variant`; a glyph without a duotone twin keeps its stroke form. */
function getAppIcon(name: AppIconName, variant: IconVariant = "stroke"): readonly IconNode[] {
	const icon = appIcons[name];
	return (variant === "duotone" ? icon.duotone : undefined) ?? icon.stroke;
}

export { appIcons, getAppIcon, type AppIconData, type AppIconName, type IconNode, type IconTag, type IconVariant };
